-- Product presentation belongs to D1; historical order snapshots are untouched.
ALTER TABLE products ADD COLUMN slug TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN category TEXT NOT NULL DEFAULT 'Kommetjes' CHECK(category IN ('Kommetjes','Aperoschalen'));
ALTER TABLE products ADD COLUMN type_label TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN images_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(images_json));
ALTER TABLE products ADD COLUMN sort_order INTEGER NOT NULL DEFAULT 0;
UPDATE products SET slug='olive',category='Kommetjes',type_label='Klein potje met groene binnenkant',images_json='[{"src":"/assets/market-stand.png","alt":"Tijdelijk beeld uit het oorspronkelijke Casa Apero sfeerbeeld. Geen foto van dit product; echte productfoto volgt.","crop":"bowls","isPlaceholder":true},{"src":"/assets/market-stand.png","alt":"Tijdelijk beeld uit het oorspronkelijke Casa Apero sfeerbeeld. Geen foto van dit product; echte productfoto volgt.","crop":"table","isPlaceholder":true}]',sort_order=0,description=CASE WHEN description='' THEN 'Handgemaakt keramieken potje met een unieke groene binnenkant. Perfect voor dips, sausjes of kleine aperohapjes.' ELSE description END WHERE id='olive';
