UPDATE products SET slug='aperitivo',category='Aperoschalen',type_label='Keramieken aperoschaal',images_json='[{"src":"/assets/market-stand.png","alt":"Tijdelijk beeld uit het oorspronkelijke Casa Apero sfeerbeeld. Geen foto van dit product; echte productfoto volgt.","crop":"platter","isPlaceholder":true},{"src":"/assets/market-stand.png","alt":"Tijdelijk beeld uit het oorspronkelijke Casa Apero sfeerbeeld. Geen foto van dit product; echte productfoto volgt.","crop":"table","isPlaceholder":true}]',sort_order=3,description=CASE WHEN description='' THEN 'Handgemaakte keramieken aperoschalen, ideaal om hapjes stijlvol te serveren tijdens gezellige momenten met vrienden en familie.' ELSE description END WHERE id='aperitivo';
CREATE UNIQUE INDEX products_slug_unique ON products(slug);
